contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // Call with any non-negative amount; this function will send Ether to c when calling addToBalance.
    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount, "insufficient balance to forward");
        // read before values
        uint beforeUserBal = c.getBalance(address(this)); if (__ESBMC_reverted()) return;
        uint beforeContractBal = address(c).balance;

        // perform the state-changing call, capturing whether it reverted
        bool reverted;
        c.addToBalance{value: amount}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // read after values
        uint afterUserBal = c.getBalance(address(this)); if (__ESBMC_reverted()) return;
        uint afterContractBal = address(c).balance;

        // General rule:
        // If the call did NOT revert, then the recorded user balance increased by exactly amount
        // and the contract's Ether balance increased by exactly amount.
        // If the call reverted, neither observable must have increased by amount (we assert only the positive case here).
        assert(reverted || (afterUserBal == beforeUserBal + amount && afterContractBal == beforeContractBal + amount));
    }

    // allow receiving refunds when withdrawBalance is exercised elsewhere
    receive() external payable {}
}

