pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Reentrance c;

    function setUp() public {
        c = new Reentrance();
    }

    function _run(uint256 amount) internal {
        amount = bound(amount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= amount);
        uint256 beforeUserBal;
        try c.getBalance(address(this)) returns (uint256 __r) { beforeUserBal = __r; } catch { return; }
        uint beforeContractBal = address(c).balance;
        bool reverted;
        try c.addToBalance{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 afterUserBal;
        try c.getBalance(address(this)) returns (uint256 __r) { afterUserBal = __r; } catch { return; }
        uint afterContractBal = address(c).balance;
        assertTrue(reverted || (afterUserBal == beforeUserBal + amount && afterContractBal == beforeContractBal + amount));
    }

    function testFuzz_run(uint256 amount) public {
        _run(amount);
    }

    receive() external payable {}
}
